        if r1<r0 or c1<c0: return
        for c in range(c0,c1+1):
            out[r0,c]=color; out[r1,c]=color
        for r in range(r0,r1+1):
            out[r,c0]=color; out[r,c1]=color
    draw(r0,c0,r1,c1,5)
    while True:
